import unittest

from spacefractions.game.game import Game
from spacefractions.game.state import GameState
from spacefractions.question.question import Question


def make_question(qid, correct=0):
    return Question(qid, f"Q{qid}?", ["a", "b", "c"], correct)


class GameTest(unittest.TestCase):
    def setUp(self):
        self.questions = [make_question(1, 0), make_question(2, 1)]
        self.game = Game(1, self.questions)

    def test_initial_state_is_playing(self):
        self.assertEqual(self.game.state, GameState.PLAYING)
        self.assertEqual(self.game.view_score(), 0)

    def test_correct_answer_increments_score(self):
        self.assertTrue(self.game.submit_answer(0))
        self.assertEqual(self.game.view_score(), 1)

    def test_wrong_answer_does_not_increment(self):
        self.assertFalse(self.game.submit_answer(2))
        self.assertEqual(self.game.view_score(), 0)

    def test_pause_and_resume(self):
        self.game.pause()
        self.assertEqual(self.game.state, GameState.PAUSED)
        self.game.resume()
        self.assertEqual(self.game.state, GameState.PLAYING)

    def test_submit_answer_while_paused_raises(self):
        self.game.pause()
        with self.assertRaises(RuntimeError):
            self.game.submit_answer(0)

    def test_game_over_after_all_questions(self):
        self.game.submit_answer(0)
        self.game.submit_answer(1)
        self.assertTrue(self.game.is_finished())
        self.assertEqual(self.game.state, GameState.GAME_OVER)

    def test_progress(self):
        self.assertEqual(self.game.progress(), (0, 2))
        self.game.submit_answer(0)
        self.assertEqual(self.game.progress(), (1, 2))

    def test_finish_returns_to_done(self):
        self.game.submit_answer(0)
        self.game.submit_answer(1)
        self.assertIsNone(self.game._machine.finish())


if __name__ == "__main__":
    unittest.main()
